CREATE TABLE users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL);
CREATE TABLE channels(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', url TEXT NOT NULL DEFAULT '');
CREATE TABLE posts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 0 CHECK(published IN (0,1)), created TEXT NOT NULL);
CREATE TABLE sheets(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, channel_id BIGINT NOT NULL REFERENCES channels(id), spreadsheet_id TEXT NOT NULL UNIQUE, range_name TEXT NOT NULL, mapping TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)), last_attempt TEXT, last_success TEXT);
CREATE TABLE entries(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sheet_id BIGINT NOT NULL REFERENCES sheets(id), external_id TEXT NOT NULL, occurred TEXT NOT NULL, stake DOUBLE PRECISION NOT NULL CHECK(stake>0), profit DOUBLE PRECISION NOT NULL, UNIQUE(sheet_id,external_id));
CREATE TABLE revisions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, entry_id BIGINT NOT NULL REFERENCES entries(id), previous TEXT NOT NULL, changed TEXT NOT NULL);
CREATE TABLE sync_logs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sheet_id BIGINT REFERENCES sheets(id), started TEXT NOT NULL, status TEXT NOT NULL, message TEXT NOT NULL);
